using System.IO;using System.Windows;using System.Windows.Controls;using System.Windows.Threading;
class History{public List<string> Items{get;}=new();public void Add(string text){if(string.IsNullOrEmpty(text)||text.Length>20000)return;Items.Remove(text);Items.Insert(0,text);if(Items.Count>50)Items.RemoveAt(50);}}
class Program{[STAThread]static int Main(string[]args){if(args.Contains("--self-test")){var testHistory=new History();testHistory.Add("one");testHistory.Add("two");testHistory.Add("one");if(testHistory.Items.Count!=2||testHistory.Items[0]!="one")return 1;for(int i=0;i<100;i++)testHistory.Add(i.ToString());return testHistory.Items.Count==50?0:1;}var app=new Application();var w=new Window{Title="Local Clipboard History",Width=950,Height=650};var panel=new DockPanel{Margin=new Thickness(18)};w.Content=panel;var bar=new StackPanel{Orientation=Orientation.Horizontal};DockPanel.SetDock(bar,Dock.Top);panel.Children.Add(bar);var status=new TextBlock{Text="Capture is OFF. Text only; history stays in memory.",Margin=new Thickness(8)};DockPanel.SetDock(status,Dock.Bottom);panel.Children.Add(status);var list=new ListBox();panel.Children.Add(list);var h=new History();bool active=false;string previous="";void Draw(){list.ItemsSource=null;list.ItemsSource=h.Items;}void Button(string name,Action action){var b=new Button{Content=name,Padding=new Thickness(10),Margin=new Thickness(4)};b.Click+=(_,_)=>{try{action();}catch(Exception e){status.Text=e.Message;}};bar.Children.Add(b);}Button("Start / stop capture",()=>{active=!active;status.Text=active?"Capturing text once per second. Sensitive clipboard text may be included.":"Capture stopped.";});Button("Copy selected",()=>{if(list.SelectedItem is string s)Clipboard.SetText(s);});Button("Clear memory",()=>{h.Items.Clear();Draw();});Button("Export selected",()=>{if(list.SelectedItem is not string s)return;var dialog=new Microsoft.Win32.SaveFileDialog{Filter="Text|*.txt"};if(dialog.ShowDialog()==true)File.WriteAllText(dialog.FileName,s);});var timer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(1)};timer.Tick+=(_,_)=>{if(!active)return;try{if(Clipboard.ContainsText()){var text=Clipboard.GetText();if(text!=previous){previous=text;h.Add(text);Draw();}}}catch(System.Runtime.InteropServices.COMException){status.Text="Clipboard busy; retrying next tick.";}};timer.Start();w.Closed+=(_,_)=>timer.Stop();app.Run(w);return 0;}}
